#include "android_cpu_backend.h"

#if defined(__ANDROID__) && defined(LLAMATIK_ANDROID_CPU_VARIANTS)

#include <android/log.h>
#include <dlfcn.h>

#include <cstdlib>
#include <cstring>

#include "ggml-backend.h"
#include "llamatik_cpu_variants.h"  // generated by CMake: LLAMATIK_CPU_VARIANT_LIBS

#define CPU_LOGI(...) __android_log_print(ANDROID_LOG_INFO,  "LlamatikCpu", __VA_ARGS__)
#define CPU_LOGE(...) __android_log_print(ANDROID_LOG_ERROR, "LlamatikCpu", __VA_ARGS__)

namespace {

using backend_score_fn = int (*)();

const char * const kVariantLibs[] = { LLAMATIK_CPU_VARIANT_LIBS };

// Returns the variant's score: 0 when this CPU lacks a feature it needs, or when it cannot be opened.
int variant_score(const char * lib) {
    void * handle = dlopen(lib, RTLD_NOW | RTLD_LOCAL);
    if (handle == nullptr) {
        CPU_LOGE("cannot open %s: %s", lib, dlerror());
        return 0;
    }
    auto score_fn = reinterpret_cast<backend_score_fn>(dlsym(handle, "ggml_backend_score"));
    const int score = score_fn != nullptr ? score_fn() : 0;
    dlclose(handle);
    return score;
}

// LLAMATIK_CPU_VARIANT (for example "android_armv8.0_1") pins one variant for testing and
// benchmarking. It is honored only when this CPU supports that variant, so it can never select code
// the device cannot run.
const char * requested_variant(int & score) {
    const char * wanted = getenv("LLAMATIK_CPU_VARIANT");
    if (wanted == nullptr || wanted[0] == '\0') {
        return nullptr;
    }
    for (const char * lib : kVariantLibs) {
        if (strstr(lib, wanted) == nullptr) {
            continue;
        }
        score = variant_score(lib);
        if (score > 0) {
            return lib;
        }
        CPU_LOGE("LLAMATIK_CPU_VARIANT=%s is not supported on this CPU; selecting automatically", wanted);
        return nullptr;
    }
    CPU_LOGE("LLAMATIK_CPU_VARIANT=%s matches no CPU variant; selecting automatically", wanted);
    return nullptr;
}

}  // namespace

// With GGML_BACKEND_DL the CPU backend is no longer linked in; each variant is a separate module
// built for one ARM feature level. ggml_backend_load_all() finds them by listing a directory, but
// an app packaged with uncompressed native libraries (useLegacyPackaging = false) keeps them inside
// the APK, where no directory exists. The dynamic linker can still open them by name, so score each
// variant the way ggml_backend_load_best() does and register the highest.
void llamatik_load_android_cpu_backend() {
    int best_score = 0;
    const char * best_lib = requested_variant(best_score);
    if (best_lib == nullptr) {
        for (const char * lib : kVariantLibs) {
            const int score = variant_score(lib);
            if (score > best_score) {
                best_score = score;
                best_lib = lib;
            }
        }
    }
    if (best_lib == nullptr) {
        CPU_LOGE("no supported ggml CPU backend variant; CPU inference is unavailable");
        return;
    }
    if (ggml_backend_load(best_lib) == nullptr) {
        CPU_LOGE("failed to register ggml CPU backend %s", best_lib);
        return;
    }
    CPU_LOGI("using ggml CPU backend %s (score %d)", best_lib, best_score);
}

#else

void llamatik_load_android_cpu_backend() {}

#endif
